args.command:
perl -e '
use strict;
use warnings;
use File::Find;
use File::Basename;

my $root = "/bench/repo";
my $internal = "$root/internal";

sub is_go {
  my ($path, $tests) = @_;
  return 0 unless $path =~ /\.go$/;
  return 0 if $path =~ m{/proto/gen/} || $path =~ m{/web/} || $path =~ m{/node_modules/};
  return 0 if !$tests && $path =~ /_test\.go$/;
  return 1;
}

my @decls;
find({ wanted => sub {
  return unless is_go($File::Find::name, 1);
  my $path = $File::Find::name;
  open my $fh, "<", $path or return;
  my $i = 0;
  while (my $line = <$fh>) {
    $i++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      my $recv_type;
      if (defined $recv) {
        my @p = split /\s+/, $recv;
        $recv_type = $p[-1];
        $recv_type =~ s/^\*//;
      }
      push @decls, {
        name => $name,
        recv => $recv_type,
        path => $path,
        line => $i,
        is_test => ($path =~ /_test\.go$/ ? 1 : 0),
      };
    }
  }
  close $fh;
}, no_chdir => 1 }, $internal);

my $total = scalar @decls;
my $nontest = grep { !$_->{is_test} } @decls;
print "Total declarations (incl tests): $total\n";
print "Non-test declarations: $nontest\n";

my %name_to_decls;
for my $d (@decls) {
  next if $d->{is_test};
  push @{$name_to_decls{$d->{name}}}, $d;
}
print "Unique non-test function names: ", scalar(keys %name_to_decls), "\n";

my @go_files;
find({ wanted => sub {
  return unless is_go($File::Find::name, 1);
  push @go_files, $File::Find::name;
}, no_chdir => 1 }, $root);

my %name_counts;
my %name_sites;
my %names = map { $_ => 1 } keys %name_to_decls;

for my $path (@go_files) {
  open my $fh, "<", $path or next;
  my $i = 0;
  while (my $line = <$fh>) {
    $i++;
    my $is_decl = 0;
    my $decl_name;
    if ($line =~ /^func\s+(?:\([^)]+\)\s+)?(\w+)\s*\(/) {
      $is_decl = 1;
      $decl_name = $1;
    }
    while ($line =~ /(?:([\w.]+)\.)?(\w+)\s*\(/g) {
      my $name = $2;
      next unless $names{$name};
      # skip declaration of this name
      if ($is_decl && $decl_name eq $name && $-[0] < 20) {
        next;
      }
      $name_counts{$name}++;
      if (scalar(@{$name_sites{$name} || []}) < 6) {
        my $rel = $path;
        $rel =~ s/^\Q$root\E\///;
        my $snip = $line;
        chomp $snip;
        $snip = substr($snip, 0, 90);
        push @{$name_sites{$name}}, "$rel:$i: $snip";
      }
    }
  }
  close $fh;
}

print "\n=== TOP 40 NAMES BY CALL-SITE COUNT ===\n";
my @ranked = sort { $name_counts{$b} <=> $name_counts{$a} } keys %name_counts;
for my $name (@ranked[0..39]) {
  last unless defined $name;
  my $cnt = $name_counts{$name};
  my @nd = @{$name_to_decls{$name}};
  my @recvs = map { $_->{recv} || "(func)" } @nd;
  my @paths = map { my $p = $_->{path}; $p =~ s/^\Q$root\E\///; $p } @nd;
  my $coll = @nd > 1 ? "collision" : "unique";
  print sprintf("%4d  %-32s decls=%d recvs=[%s] paths=[%s] %s\n", $cnt, $name, scalar(@nd), join(",", @recvs), join(",", @paths), $coll);
}

print "\n=== TOP NAME SAMPLE SITES ===\n";
for my $name (@ranked[0..7]) {
  last unless defined $name;
  print "\n--- $name ($name_counts{$name}) ---\n";
  for my $s (@{$name_sites{$name}}) {
    print "  $s\n";
  }
}
'

