perl -e '
use strict;
use warnings;

my $root = "/bench/repo";
my $internal = "$root/internal";

sub is_go {
  my ($path, $tests) = @_;
  return 0 unless $path =~ /\.go$/;
  return 0 if $path =~ m{/proto/gen/} || $path =~ m{/web/} || $path =~ m{/node_modules/} || $path =~ m{/\.git/};
  return 0 if !$tests && $path =~ /_test\.go$/;
  return 1;
}

my @internal_files = grep { is_go($_, 1) } split /\n/, `find "$internal" -name "*.go" -type f`;
my @go_files = grep { is_go($_, 1) } split /\n/, `find "$root" -name "*.go" -type f ! -path "*/.git/*" ! -path "*/web/*" ! -path "*/proto/gen/*"`;

my @decls;
for my $path (@internal_files) {
  open my $fh, "<", $path or next;
  my $i = 0;
  while (my $line = <$fh>) {
    $i++;
