      my $recv_type;
      if (defined $recv) {
        my @p = split /\s+/, $recv;
        $recv_type = $p[-1];
        $recv_type =~ s/^\*//;
      }
      push @decls, {
        name => $name,
        recv => $recv_type,
        path => $path,
        line => $i,
        is_test => ($path =~ /_test\.go$/ ? 1 : 0),
      };
    }
  }
  close $fh;
}

my $total = scalar @decls;
my $nontest = grep { !$_->{is_test} } @decls;
print "Total declarations (incl tests): $total\n";
print "Non-test declarations: $nontest\n";
print "Go files scanned: ", scalar(@go_files), "\n";

my %name_to_decls;
for my $d (@decls) {
  next if $d->{is_test};
